api.look('agent');
const w=api.w, cx=w/2, top=190, gx=cx-150, cell=60;
api.text('Launch Friday', cx, 100, {size:38, weight:'bold', align:'center', k:api.seg(t,0,0.8)});
for(let i=0;i<20;i++){
  const r=Math.floor(i/4), col=i%4;
  const x=gx+col*cell*1.25+cell/2, y=top+r*cell*1.3+cell/2+20;
  const k=api.stag(t,i,{gap:0.06,dur:0.4,from:0.3});
  const c=i<14?'good':i<17?'warn':'dim';
  api.box(x,y,50,50,{c, fill:i<17?c:null, a:0.35+0.65*k, k});
  if(i<14) api.shape('check',x,y,26,{c:'ink',k:api.seg(t,1.4+i*0.03,2)});
}
api.say('14 of 20 are done', 0.4, 3.5);

api.look('agent');
const w=api.w, cx=w/2, cy=330;
const k=api.seg(t,0,2.2);
api.donut([{v:14,c:'good'},{v:3,c:'warn'},{v:3,c:'dim'}], cx, cy, 130, {k});
api.counter(14, cx, cy-10, {k, size:80, suf:'', c:'good'});
api.text('of 20 done', cx, cy+50, {size:24, align:'center', k:api.seg(t,1,2)});
api.progress(40, cy+200, w-80, 22, 0.7, {k:api.seg(t,1.5,3.5), c:'good'});
api.text('70%', cx, cy+260, {size:30, weight:'bold', align:'center', c:'good', k:api.seg(t,3,4)});
api.focus(cx, cy, api.lerp(1,1.12,api.ease(api.seg(t,0,5))));
api.say('Most of the work is shipped', 0.4, 4.5);

api.look('agent');
const w=api.w, cx=w/2;
api.text('Blocked', cx, 120, {size:36, weight:'bold', align:'center', c:'warn', k:api.seg(t,0,0.8)});
const A=api.node(cx,330,220,90,'App Review',{icon:'lock',k:api.seg(t,0.5,1.5),pop:1,c:'warn'});
for(let i=0;i<3;i++){
  const x=cx-110+i*110, y=560;
  const B=api.node(x,y,96,70,'Task '+(i+1),{k:api.seg(t,1.2+i*0.4,2.2+i*0.4),pop:1,c:'warn'});
  api.link(B,A,{k:api.seg(t,2+i*0.4,3+i*0.4),c:'warn',flow:t,bend:0});
}
api.scribble(cx,330,140,70,{k:api.seg(t,3.5,4.5),c:'bad'});
api.say('Three wait on App Review', 0.4, 5.5);

api.look('agent');
const w=api.w, cx=w/2;
api.text('Not started', cx, 120, {size:36, weight:'bold', align:'center', c:'dim', k:api.seg(t,0,0.8)});
for(let i=0;i<3;i++){
  const x=cx-110+i*110, y=360;
  const k=api.stag(t,i,{gap:0.4,dur:0.6,from:0.6});
  api.box(x,y,90,90,{c:'dim', dash:[6,6], k});
  api.shape('plus',x,y,32,{c:'dim',k});
}
api.brace(cx-165,440,cx+165,440,{k:api.seg(t,2,3)});
api.text('3 to go', cx, 500, {size:30, align:'center', k:api.seg(t,2.4,3.4)});
api.say('Three still to begin', 0.4, 4.5);

api.look('agent');
const w=api.w, cx=w/2;
api.timeline([{t:'Today',s:'14 done'},{t:'Wed',s:'Review'},{t:'Thu',s:'Finish'},{t:'Fri',s:'Launch'}], 50, 330, w-100, {k:api.seg(t,0,3)});
const k=api.seg(t,3,4.5);
api.shape('bell', cx, 560, 60, {c:'accent', k});
api.glow(cx,560,80*k,{c:'accent'});
api.text('Friday', cx, 640, {size:34, weight:'bold', align:'center', c:'accent', k});
api.say('Launch is Friday', 0.4, 5.5);
